  function _checkCdnNow() {
    var btn = document.getElementById("_eli3_tm_checknow");
    if (btn) { btn.disabled = true; btn.textContent = "⏳ Checking…"; }
    var hasFetch = !!(eli.get && typeof eli.get("build_draft", "fetchManifest") === "function");
    if (!hasFetch) {
      _toast("Build Draft needs update — fetchManifest dispatch missing.", "err");
      if (btn) { btn.disabled = false; btn.textContent = "🔍 Check CDN Now"; }
      return;
    }
    eli.dispatch("build_draft", "fetchManifest").then(function (manifest) {
      if (!manifest || !Array.isArray(manifest.templates)) {
        _toast("No template manifest on CDN yet — push at least one template first.", "info");
        return;
      }
      var ident = (eli.tools && typeof eli.tools.userIdentity === "function") ? eli.tools.userIdentity() : {};
