      var coreBadge = t.core
        ? '<span style="font:800 9px Inter,sans-serif;color:#7c2d12;background:#fed7aa;border:1px solid #ea580c;padding:2px 6px;letter-spacing:0.08em;text-transform:uppercase;">⭐ Core</span>'
        : '<span style="font:800 9px Inter,sans-serif;color:#475569;background:#e2e8f0;border:1px solid #cbd5e1;padding:2px 6px;letter-spacing:0.08em;text-transform:uppercase;">Lazy</span>';
      var pubBadge = isPublished
        ? '<span style="font:800 9px Inter,sans-serif;color:#14532d;background:#dcfce7;border:1px solid #16a34a;padding:2px 6px;letter-spacing:0.08em;text-transform:uppercase;">🟢 Published</span>'
        : '<span style="font:800 9px Inter,sans-serif;color:#92400e;background:#fef3c7;border:1px solid #f59e0b;padding:2px 6px;letter-spacing:0.08em;text-transform:uppercase;">🟡 Local Only</span>';
      var diffBadge = localAhead
        ? '<span title="Local IDB row is newer than the CDN copy — push to sync." style="font:800 9px Inter,sans-serif;color:#92400e;background:#fef3c7;border:1px solid #f59e0b;padding:2px 6px;letter-spacing:0.08em;text-transform:uppercase;">📝 Edited since push</span>'
        : "";
      // 2026-05-22 v2: switched from relative ("5 min ago") to absolute
      // date+time per request. Compact format so the metadata line stays
      // single-row: "5/22/26 2:32 PM".
      var editedAbs = _shortDateTime(t.modifiedAt);
      var pubAbs    = isPublished ? _shortDateTime(t.publishedAt) : "never";
      var editedFull = _absoluteDate(t.modifiedAt);
      var pubFull    = isPublished ? _absoluteDate(t.publishedAt) : "Not yet published to CDN";
      var leftBorder = t.core ? "#ea580c" : "#cbd5e1";
      // Editable field renderer — text-like input that highlights on
      // hover, becomes properly editable on focus. Auto-saves on blur.
      function _editable(field, value, opts) {
        opts = opts || {};
        var ph = opts.placeholder || "";
        // 2026-05-22 v3: tightened font sizes — name 13px (was 16),
        // others 11.5px (was 12). Padding 2px 6px (was 4px 7px).
        var bigFont = opts.big ? "font:700 13px/1.2 Inter,sans-serif;color:#0f172a;" : "font:500 11.5px/1.25 Inter,sans-serif;color:#0f172a;";
        return '<input class="_eli3_tm_field" data-tm-id="' + _esc(t.id) + '" data-tm-field="' + _esc(field) + '" type="text" value="' + _esc(value || "") + '" placeholder="' + _esc(ph) + '" ' +
          'style="' + bigFont +
          'width:100%;padding:2px 6px;background:transparent;border:1px solid transparent;border-radius:3px;box-sizing:border-box;outline:none;transition:background 0.12s, border-color 0.12s;" ' +
          'onmouseover="this.style.background=\'#f8fafc\';this.style.borderColor=\'#cbd5e1\';" ' +
          'onmouseout="if(document.activeElement!==this){this.style.background=\'transparent\';this.style.borderColor=\'transparent\';}" ' +
          'onfocus="this.style.background=\'#fff\';this.style.borderColor=\'#c9a227\';" ' +
          'onblur="this.style.background=\'transparent\';this.style.borderColor=\'transparent\';">';
      }
      // 2026-05-22 v4: two-row default layout. Row 1 = name + badges +
      // Push. Row 2 = metadata (size, edited, published) + expand arrow.
      // EVERYTHING else (agreement type, Core/Default checkboxes,
      // audience emails / groups / aliases) hides under the arrow.
      // Maximum vertical density — fits ~12-15 cards per screen.
      var isExpanded = !!_state.expandedAdvanced[t.id];
      var arrow = isExpanded ? "▼" : "▶";
      return '<div class="_eli3_tm_card" data-tm-id="' + _esc(t.id) + '" style="background:#fff;border:1px solid #e2e8f0;border-left:4px solid ' + leftBorder + ';padding:6px 10px;margin-bottom:5px;">' +
        // ROW 1: name + badges + Push button
        '<div style="display:flex;justify-content:space-between;align-items:center;gap:8px;">' +
          '<div style="min-width:0;flex:1;display:flex;align-items:center;gap:6px;flex-wrap:wrap;">' +
            '<div style="min-width:180px;flex:1;">' + _editable("name", t.name || t.id, { big: true, placeholder: "Display name (hover to edit)" }) + '</div>' +
            coreBadge + pubBadge + diffBadge +
          '</div>' +
          (isPublished ? '<button class="_eli3_tm_back" data-tm-id="' + _esc(t.id) + '" title="Publish again the version the last push replaced" style="padding:4px 8px;font-size:10.5px;font-weight:800;color:#334155;background:linear-gradient(180deg,#fff,#e2e8f0);border:1px solid #cbd5e1;cursor:pointer;flex-shrink:0;">↶ Roll back</button>' : '') +
          '<button class="_eli3_tm_push" data-tm-id="' + _esc(t.id) + '" style="padding:4px 10px;font-size:10.5px;font-weight:800;color:#fff;background:linear-gradient(180deg,#16a34a,#15803d);border:1px solid #15803d;cursor:pointer;text-transform:uppercase;letter-spacing:0.08em;flex-shrink:0;">📤 Push</button>' +
        '</div>' +
        // ROW 2: metadata + arrow toggle (clickable to expand/collapse)
        '<div class="_eli3_tm_toggle_adv" data-tm-id="' + _esc(t.id) + '" style="font:500 10px/1.3 Inter,sans-serif;color:#94a3b8;display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:3px;cursor:pointer;user-select:none;">' +
          '<span style="font-size:9px;color:#475569;font-weight:700;">' + arrow + '</span>' +
          '<span>' + sizeLabel + '</span>' +
          '<span title="' + _esc(editedFull) + '" style="color:' + (localAhead ? "#92400e" : "#94a3b8") + ';font-weight:' + (localAhead ? "700" : "500") + ';">✏️ ' + editedAbs + '</span>' +
          '<span title="' + _esc(pubFull) + '" style="color:' + (isPublished ? "#94a3b8" : "#92400e") + ';">☁ ' + pubAbs + '</span>' +
          // Initials of whoever last pushed this template to the CDN.
          (isPublished && t.publishedBy
            ? '<span title="Last pushed by ' + _esc(t.publishedBy) + '" style="font:800 9px Inter,sans-serif;color:#1565c0;background:#e0edfb;border:1px solid #93c5fd;padding:1px 5px;border-radius:3px;letter-spacing:0.04em;">by ' + _esc(_initialsFromEmail(t.publishedBy)) + '</span>'
            : '') +
          (isPublished ? '<span>· ' + Math.round((t.publishedSize || 0) / 1024) + ' KB on CDN</span>' : '') +
        '</div>' +
        // EXPANDED SECTION (hidden by default) — everything else.
        (isExpanded ? (
          '<div style="margin-top:6px;padding-top:6px;border-top:1px dashed #e2e8f0;">' +
            // Agreement type
            '<div style="display:flex;align-items:center;gap:8px;margin-bottom:3px;">' +
              '<span style="font:800 9px Inter,sans-serif;text-transform:uppercase;letter-spacing:0.12em;color:#475569;flex-shrink:0;min-width:100px;">Agreement Type:</span>' +
              _editable("agreementType", t.agreementType, { placeholder: "e.g. NDA, MSA, SOW (hover to edit)" }) +
            '</div>' +
            // Core + Default checkboxes
            '<div style="display:flex;gap:14px;margin-bottom:3px;padding:3px 6px;background:#fafafa;border:1px solid #f1f5f9;border-radius:3px;">' +
              '<label style="display:inline-flex;align-items:center;gap:5px;cursor:pointer;font:600 10.5px Inter,sans-serif;color:#7c2d12;">' +
                '<input class="_eli3_tm_check" data-tm-id="' + _esc(t.id) + '" data-tm-field="core" type="checkbox"' + (t.core ? " checked" : "") + ' style="width:13px;height:13px;cursor:pointer;">' +
                '⭐ Core' +
              '</label>' +
              '<label style="display:inline-flex;align-items:center;gap:5px;cursor:pointer;font:600 10.5px Inter,sans-serif;color:#1e3a8a;">' +
                '<input class="_eli3_tm_check" data-tm-id="' + _esc(t.id) + '" data-tm-field="defaultForType" type="checkbox"' + (t.defaultForType ? " checked" : "") + ' style="width:13px;height:13px;cursor:pointer;">' +
                '🎯 Default for type' +
              '</label>' +
            '</div>' +
            // Audience emails
            '<div style="display:flex;align-items:center;gap:8px;margin-bottom:3px;">' +
              '<span style="font:800 9px Inter,sans-serif;text-transform:uppercase;letter-spacing:0.12em;color:#475569;flex-shrink:0;min-width:100px;">Audience Emails:</span>' +
              _editable("audienceEmailsCsv", (t.audienceEmails || []).join(", "), { placeholder: "Empty = all users (comma-separated)" }) +
            '</div>' +
            // Audience groups
            '<div style="display:flex;align-items:center;gap:8px;margin-bottom:3px;">' +
              '<span style="font:800 9px Inter,sans-serif;text-transform:uppercase;letter-spacing:0.12em;color:#475569;flex-shrink:0;min-width:100px;">Audience Groups:</span>' +
              _editable("audienceGroupsCsv", (t.audienceGroups || []).join(", "), { placeholder: "Empty = no group restriction (comma-separated)" }) +
            '</div>' +
            // OARS aliases
            '<div style="display:flex;align-items:center;gap:8px;margin-bottom:3px;">' +
              '<span style="font:800 9px Inter,sans-serif;text-transform:uppercase;letter-spacing:0.12em;color:#475569;flex-shrink:0;min-width:100px;">OARS Aliases:</span>' +
              _editable("aliasesCsv", (t.aliases || []).join(", "), { placeholder: "Optional alternative phrasings OARS might emit (comma-separated)" }) +
            '</div>' +
            // ID footer
            '<div style="font:500 9.5px monospace;color:#cbd5e1;margin-top:3px;">' + _esc(t.id) + '</div>' +
          '</div>'
        ) : '') +
      '</div>';
    }).join("");
    // Wire auto-save on every editable text input — saves on blur,
    // no toast (no noise). Per-field validation/normalization happens
    // in _saveField.
    el.querySelectorAll("._eli3_tm_field").forEach(function (inp) {
      inp.addEventListener("blur", function () {
        var id = inp.getAttribute("data-tm-id");
        var field = inp.getAttribute("data-tm-field");
        _saveField(id, field, inp.value);
      });
      // Save on Enter too so the user can confirm a change without tabbing.
      inp.addEventListener("keydown", function (ev) {
        if (ev.key === "Enter") { ev.preventDefault(); inp.blur(); }
      });
    });
    // Checkboxes save immediately on change.
    el.querySelectorAll("._eli3_tm_check").forEach(function (cb) {
      cb.addEventListener("change", function () {
        var id = cb.getAttribute("data-tm-id");
        var field = cb.getAttribute("data-tm-field");
        _saveField(id, field, cb.checked);
      });
    });
    // Push buttons.
    el.querySelectorAll("._eli3_tm_push").forEach(function (btn) {
      btn.onclick = function (ev) {
        ev.stopPropagation();
        var id = btn.getAttribute("data-tm-id");
        _pushOne(id, btn);
      };
    });
    // [TPL-ROLLBACK] Roll back buttons: one step back, after the owner says so.
    el.querySelectorAll("._eli3_tm_back").forEach(function (btn) {
      btn.onclick = function (ev) {
        ev.stopPropagation();
        var t = _state.templates.find(function (r) { return r.id === btn.getAttribute("data-tm-id"); });
        if (!t || !eli.ui || typeof eli.ui.confirm !== "function") return;
        eli.ui.confirm({ title: "Roll back '" + (t.name || t.id) + "'?", message: "Publishes again the version the last push replaced. Everyone gets it at their next template check.", confirmLabel: "Roll back", cancelLabel: "Keep" }).then(function (yes) {
          if (!yes) return;
          btn.disabled = true; btn.textContent = "⏳ Rolling back…";
          _rollbackTemplate(t).then(function () { _toast("↶ Rolled back '" + (t.name || t.id) + "'", "ok"); _refresh(); },
            function (e) { btn.disabled = false; btn.textContent = "↶ Roll back"; _toast("Roll back failed: " + (e && e.message), "err"); });
        });
      };
    });
    // Expand/collapse the advanced fields section.
    el.querySelectorAll("._eli3_tm_toggle_adv").forEach(function (toggle) {
      toggle.onclick = function () {
        var id = toggle.getAttribute("data-tm-id");
        if (_state.expandedAdvanced[id]) delete _state.expandedAdvanced[id];
        else _state.expandedAdvanced[id] = true;
        _renderList();
      };
    });
  }

  // ── Auto-save individual fields on blur/change ────────────────────
  // No toast — auto-save is silent. Updates _state in place AND writes
  // to IDB. Re-renders ONLY the badges that depend on this field (full
  // re-render would lose input focus position). For simplicity, we
  // skip re-render entirely — the user sees their typed value as the
  // truth + the next refresh will reconcile.
  function _saveField(id, field, value) {
    var t = _state.templates.find(function (r) { return r.id === id; });
    if (!t) return;
    if (field === "audienceEmailsCsv") {
      t.audienceEmails = String(value || "").split(",")
        .map(function (s) { return s.trim().toLowerCase(); })
        .filter(Boolean);
    } else if (field === "audienceGroupsCsv") {
      t.audienceGroups = String(value || "").split(",")
        .map(function (s) { return s.trim(); })
        .filter(Boolean);
    } else if (field === "aliasesCsv") {
      t.aliases = String(value || "").split(",")
        .map(function (s) { return s.trim(); })
        .filter(Boolean);
    } else if (field === "name") {
      t.name = String(value || "").trim() || t.id;
    } else if (field === "agreementType") {
      t.agreementType = String(value || "").trim();
    } else if (field === "core" || field === "defaultForType") {
      t[field] = !!value;
    } else {
      return; // unknown field
    }
    t.modifiedAt = new Date().toISOString();
    _putTemplate(t).then(function () {
      eli.log.event("tool", "template_manager_field_saved", {
        id: id, field: field,
      });
      // For badge-affecting fields (core, defaultForType), re-render
      // so the badge updates. For text fields, skip re-render (would
      // lose focus on the next-tabbed field).
      if (field === "core" || field === "defaultForType") {
        _refresh();
      }
    }).catch(function (e) {
      _toast("Auto-save failed: " + (e && e.message), "err");
    });
  }

  function _relativeDate(iso) {
    if (!iso) return "never";
    try {
      var d = new Date(iso);
      var diff = (Date.now() - d.getTime()) / 1000;
      if (diff < 60) return "just now";
      if (diff < 3600) return Math.floor(diff / 60) + " min ago";
      if (diff < 86400) return Math.floor(diff / 3600) + " hr ago";
      if (diff < 604800) return Math.floor(diff / 86400) + " d ago";
      // After a week, switch to absolute "May 22, 2026" — relative
      // dates beyond a week aren't useful ("47 d ago" is hard to parse).
      return d.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
    } catch (_e) { return iso; }
  }
  // Full absolute "May 22, 2026 · 2:32 PM" for the title= tooltip
  // (hover-revealed precise timestamp on top of the relative display).
  function _absoluteDate(iso) {
    if (!iso) return "—";
    try {
      var d = new Date(iso);
      return d.toLocaleString("en-US", {
        year: "numeric", month: "short", day: "numeric",
        hour: "numeric", minute: "2-digit",
      });
    } catch (_e) { return iso; }
  }
  // Compact "5/22/26 2:32 PM" — used in card metadata rows where
  // horizontal space is tight. About 14 chars vs 21 for the full form.
  function _shortDateTime(iso) {
    if (!iso) return "—";
    try {
      var d = new Date(iso);
      return d.toLocaleString("en-US", {
        month: "numeric", day: "numeric", year: "2-digit",
        hour: "numeric", minute: "2-digit",
      });
    } catch (_e) { return iso; }
  }

  function _pushOne(id, btn) {
    var t = _state.templates.find(function (r) { return r.id === id; });
    if (!t) { _toast("Template not found.", "err"); return; }
    // 2026-05-22: live progress on the button. Each push phase updates
    // the button text + dims the background so the user sees real
    // motion through Reading SHA → Uploading → Updating manifest →
    // Verifying CDN → Saving locally → ✅ Pushed. On failure: ❌ stays
    // for 3s with red background, then resets. Width stretches with
    // the longer status text but the card has horizontal room.
    var origBg = "";
    function _setBtnState(text, bg, disabled) {
      if (!btn) return;
      btn.disabled = !!disabled;
      btn.textContent = text;
      if (bg !== undefined) btn.style.background = bg;
    }
    _setBtnState("⏳ Starting…", "linear-gradient(180deg,#f59e0b,#d97706)", true);
    var go = function (force) { return _publishTemplate(t, {
      force: force,
      onProgress: function (phase) {
        _setBtnState("⏳ " + phase, "linear-gradient(180deg,#f59e0b,#d97706)", true);
      },
    }); };
    return go(false).catch(function (e) {
      // [TPL-CHECKS] the checks failed: what they found, and the owner's call
      if (!e || e.code !== "TPL_CHECKS" || !eli.ui || typeof eli.ui.confirm !== "function") throw e;
      var errs = e.checks.issues.filter(function (i) { return i.sev === "error"; });
      return eli.ui.confirm({ title: "Template checks found " + errs.length + " problem" + (errs.length === 1 ? "" : "s"),
        message: errs.slice(0, 8).map(function (i) { return (i.p != null ? "¶" + i.p + ": " : "") + i.msg; }).join("\n") + (errs.length > 8 ? "\n… and " + (errs.length - 8) + " more" : "") +
          "\n\nChecked: " + e.checks.questions + " questions, " + e.checks.blocks + " IF blocks, " + e.checks.fills + " test fills." + (e.checks.before ? " Since the published version: " + e.checks.before.added + " paragraphs new, " + e.checks.before.gone + " gone." : "") + "\n\nPublish anyway?",
        confirmLabel: "Publish anyway", cancelLabel: "Don't publish" }).then(function (yes) { if (!yes) throw new Error("not published — the template checks found problems"); return go(true); });
    }).then(function (r) {
      _setBtnState("✅ Pushed", "linear-gradient(180deg,#16a34a,#15803d)", true);
      _toast("✅ Pushed '" + (t.name || id) + "' · " + Math.round(r.size / 1024) + " KB · " + _absoluteDate(r.publishedAt), "ok");
      // Hold success state for ~1.5s before restoring to plain Push,
      // then trigger a refresh so the row's badges/timestamps update.
      setTimeout(function () {
        _setBtnState("📤 Push", "", false);
        if (btn) btn.style.background = "linear-gradient(180deg,#16a34a,#15803d)";
        _refresh();
      }, 1500);
    }).catch(function (e) {
      _setBtnState("❌ Failed", "linear-gradient(180deg,#dc2626,#991b1b)", true);
      _toast("Push failed: " + (e && e.message), "err");
      // Hold failure state for 3s so the user notices, then restore.
      setTimeout(function () {
        _setBtnState("📤 Push", "", false);
        if (btn) btn.style.background = "linear-gradient(180deg,#16a34a,#15803d)";
      }, 3000);
    });
  }


  // ── Tile + dispatch entry ─────────────────────────────────────────
  eli.register({
    tile: { app_template_manager: _open },
    template_manager: {
      open: _open,
      publish: function (id) {
        return _loadAllTemplates().then(function (rows) {
          var t = rows.find(function (r) { return r.id === id; });
          if (!t) throw new Error("Template not found: " + id);
          return _publishTemplate(t);
        });
      },
      // [TPL-REVISE] Template Revise's templates, the same checks, and its publish (checks and the kept version as any publish)
      list: function () { return _loadAllTemplates(); },
      checks: function (content, prevContent) { return _tplChecks(_tplParas(content), prevContent ? _tplParas(prevContent) : null); },
      publishContent: function (id, content, opts) {
        opts = opts || {};
        return _loadAllTemplates().then(function (rows) {
          var t = rows.find(function (r) { return r.id === id; });
          if (!t) throw new Error("Template not found: " + id);
          return _publishTemplate(Object.assign({}, t, { content: content }), { force: !!opts.force, onProgress: opts.onProgress });
        });
      },
    },
  });
  eli.log.event("tool", "template_manager_init", { email: userEmail });
}
